{
  "name": "Kanji Pratik - Yazma ve Ezberleme",
  "description": "Japonca Kanji karakterlerini ezberlemek ve yazma pratiği yapmak için tasarlanmış, modern ve mobil uyumlu bir eğitim uygulaması."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface KanjiItem {
  id: number;
  week: number;
  kanji: string;
  reading: string;
  meaning: string;
}

export enum AppMode {
  FLASHCARD = 'FLASHCARD',
  DRAWING = 'DRAWING'
}

export type WeekFilter = 'Tümü' | '9' | '10' | '11' | '12';

import React, { useState, useMemo, useCallback } from 'react';
import { 
  Menu, 
  ChevronLeft, 
  ChevronRight, 
  RefreshCw, 
  Layers, 
  PenTool, 
  Filter, 
  Shuffle, 
  BookOpen 
} from 'lucide-react';
import { kanjiData } from './data/kanjiData';
import { AppMode, KanjiItem, WeekFilter } from './types';
import Flashcard from './components/Flashcard';
import DrawingBoard from './components/DrawingBoard';

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>(AppMode.FLASHCARD);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [weekFilter, setWeekFilter] = useState<WeekFilter>('Tümü');
  const [shuffledData, setShuffledData] = useState<KanjiItem[]>([...kanjiData]);

  // Derived filtered data
  const filteredData = useMemo(() => {
    if (weekFilter === 'Tümü') return shuffledData;
    return shuffledData.filter(item => item.week === parseInt(weekFilter));
  }, [weekFilter, shuffledData]);

  // Handle index safety
  const currentItem = filteredData[currentIdx % filteredData.length] || filteredData[0];

  const nextItem = useCallback(() => {
    setCurrentIdx((prev) => (prev + 1) % filteredData.length);
  }, [filteredData.length]);

  const prevItem = useCallback(() => {
    setCurrentIdx((prev) => (prev - 1 + filteredData.length) % filteredData.length);
  }, [filteredData.length]);

  const shuffleData = () => {
    const newShuffled = [...shuffledData].sort(() => Math.random() - 0.5);
    setShuffledData(newShuffled);
    setCurrentIdx(0);
  };

  const handleFilterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setWeekFilter(e.target.value as WeekFilter);
    setCurrentIdx(0);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-4 py-3 sm:px-6">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-600 p-1.5 rounded-lg text-white">
              <BookOpen size={20} />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">
              Kanji Pratik
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <div className="relative inline-block">
              <select 
                value={weekFilter}
                onChange={handleFilterChange}
                className="appearance-none bg-slate-100 border border-slate-200 text-slate-700 py-1.5 pl-3 pr-10 rounded-full text-sm font-medium focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"
              >
                <option value="Tümü">Tümü</option>
                <option value="9">9. Hafta</option>
                <option value="10">10. Hafta</option>
                <option value="11">11. Hafta</option>
                <option value="12">12. Hafta</option>
              </select>
              <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-slate-500">
                <Filter size={14} />
              </div>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 w-full max-w-4xl mx-auto p-4 sm:p-6 flex flex-col">
        {/* Mode Tabs */}
        <div className="flex p-1 bg-slate-200 rounded-xl mb-6 self-center w-full max-w-xs sm:max-w-sm">
          <button 
            onClick={() => setMode(AppMode.FLASHCARD)}
            className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-semibold transition-all ${
              mode === AppMode.FLASHCARD 
                ? 'bg-white text-indigo-600 shadow-sm' 
                : 'text-slate-600 hover:text-slate-800'
            }`}
          >
            <Layers size={18} />
            Flashcard
          </button>
          <button 
            onClick={() => setMode(AppMode.DRAWING)}
            className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-semibold transition-all ${
              mode === AppMode.DRAWING 
                ? 'bg-white text-indigo-600 shadow-sm' 
                : 'text-slate-600 hover:text-slate-800'
            }`}
          >
            <PenTool size={18} />
            Çizim
          </button>
        </div>

        {/* Action Bar */}
        <div className="flex justify-between items-center mb-6">
          <span className="text-sm font-medium text-slate-500 bg-slate-200/50 px-3 py-1 rounded-full">
            {currentIdx + 1} / {filteredData.length} Kelime
          </span>
          <button 
            onClick={shuffleData}
            className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider text-indigo-600 hover:text-indigo-700 px-3 py-1.5 border border-indigo-200 rounded-lg hover:bg-indigo-50 transition-colors"
          >
            <Shuffle size={14} />
            Karıştır
          </button>
        </div>

        {/* Content Area */}
        <div className="flex-1 flex flex-col justify-center items-center">
          {filteredData.length > 0 ? (
            <div className="w-full flex flex-col items-center">
              {mode === AppMode.FLASHCARD ? (
                <Flashcard item={currentItem} />
              ) : (
                <DrawingBoard item={currentItem} />
              )}
            </div>
          ) : (
            <div className="text-center py-20">
              <p className="text-slate-500">Bu hafta için veri bulunamadı.</p>
            </div>
          )}
        </div>

        {/* Navigation Controls */}
        <div className="mt-8 flex items-center justify-center gap-4 sm:gap-6 sticky bottom-4">
          <button 
            onClick={prevItem}
            className="flex items-center justify-center w-14 h-14 bg-white border border-slate-200 rounded-full text-slate-600 shadow-md hover:shadow-lg active:scale-95 transition-all"
          >
            <ChevronLeft size={28} />
          </button>

          <button 
            onClick={nextItem}
            className="flex items-center justify-center w-20 h-20 bg-indigo-600 rounded-full text-white shadow-lg hover:bg-indigo-700 active:scale-95 transition-all"
          >
            <ChevronRight size={36} />
          </button>
        </div>
      </main>

      {/* Footer Decoration */}
      <footer className="py-4 text-center text-slate-400 text-xs">
        &copy; 2024 Kanji Pratik &middot; Japon Estetiğiyle Tasarlandı
      </footer>
    </div>
  );
};

export default App;

