import React, { useRef, useState, useEffect, useCallback } from 'react';
import { Eraser, Eye, EyeOff } from 'lucide-react';
import { KanjiItem } from '../types';

interface DrawingBoardProps {
  item: KanjiItem;
}

const DrawingBoard: React.FC<DrawingBoardProps> = ({ item }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [showGuide, setShowGuide] = useState(true);

  const clearCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  }, []);

  const initCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    // Set canvas dimensions with high DPI support
    const dpr = window.devicePixelRatio || 1;
    const size = container.clientWidth;

    canvas.width = size * dpr;
    canvas.height = size * dpr;
    canvas.style.width = `${size}px`;
    canvas.style.height = `${size}px`;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#1e293b'; // slate-800
    ctx.lineWidth = 12;

    clearCanvas();
  }, [clearCanvas]);

  useEffect(() => {
    initCanvas();
    window.addEventListener('resize', initCanvas);
    return () => window.removeEventListener('resize', initCanvas);
  }, [initCanvas, item]);

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    setIsDrawing(true);
    draw(e);
  };

  const endDrawing = () => {
    setIsDrawing(false);
    const ctx = canvasRef.current?.getContext('2d');
    if (ctx) ctx.beginPath();
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const rect = canvas.getBoundingClientRect();
    let x, y;

    if ('touches' in e) {
      // Prevent scrolling while drawing
      if (e.cancelable) e.preventDefault();
      x = e.touches[0].clientX - rect.left;
      y = e.touches[0].clientY - rect.top;
    } else {
      x = e.clientX - rect.left;
      y = e.clientY - rect.top;
    }

    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.moveTo(x, y);
  };

  return (
    <div className="w-full max-w-lg flex flex-col gap-4">
      <div className="text-center space-y-1">
        <h3 className="text-2xl font-bold text-slate-800 kanji-font">
          {item.reading}
        </h3>
        <p className="text-slate-500 italic">"{item.meaning}"</p>
      </div>

      <div className="relative group" ref={containerRef}>
        {/* Trace Guide Background */}
        <div 
          className={`absolute inset-0 flex items-center justify-center pointer-events-none transition-opacity duration-300 ${
            showGuide ? 'opacity-10' : 'opacity-0'
          }`}
        >
          <span className="text-[12rem] sm:text-[18rem] font-bold text-slate-900 kanji-font select-none">
            {item.kanji}
          </span>
        </div>

        {/* Drawing Canvas */}
        <canvas
          ref={canvasRef}
          onMouseDown={startDrawing}
          onMouseUp={endDrawing}
          onMouseMove={draw}
          onMouseOut={endDrawing}
          onTouchStart={startDrawing}
          onTouchEnd={endDrawing}
          onTouchMove={draw}
          className="bg-white rounded-2xl shadow-inner border border-slate-200 cursor-crosshair touch-none"
        />

        {/* Floating Toolbar */}
        <div className="absolute bottom-4 right-4 flex gap-2">
          <button 
            onClick={() => setShowGuide(!showGuide)}
            className={`p-3 rounded-full shadow-lg transition-all ${
              showGuide ? 'bg-indigo-600 text-white' : 'bg-white text-slate-600'
            }`}
            title={showGuide ? "Rehberi Gizle" : "Rehberi Göster"}
          >
            {showGuide ? <EyeOff size={20} /> : <Eye size={20} />}
          </button>
          <button 
            onClick={clearCanvas}
            className="p-3 bg-white text-pink-500 rounded-full shadow-lg hover:text-pink-600 transition-all"
            title="Temizle"
          >
            <Eraser size={20} />
          </button>
        </div>
      </div>

      <div className="text-center">
        <p className="text-xs text-slate-400 font-medium tracking-wide uppercase">
          Ekrana dokunarak veya fareyle Kanji'yi çiz
        </p>
      </div>
    </div>
  );
};

export default DrawingBoard;

