import React, { useRef, useState, useEffect, useCallback } from 'react';
import { Eraser, Eye, EyeOff, Settings, Maximize, RotateCcw, CheckCircle2, Award } from 'lucide-react';
import { KanjiItem } from '../types';

interface DrawingBoardProps {
  item: KanjiItem;
}

const DrawingBoard: React.FC<DrawingBoardProps> = ({ item }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [isDrawing, setIsDrawing] = useState(false);
  const [showGuide, setShowGuide] = useState(true);
  const [showSettings, setShowSettings] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  // History stack for Undo
  const [history, setHistory] = useState<ImageData[]>([]);

  // Customization states
  const [guideOpacity, setGuideOpacity] = useState(15); 
  const [guideSize, setGuideSize] = useState(250);

  const getCtx = useCallback(() => {
    const canvas = canvasRef.current;
    return canvas ? canvas.getContext('2d', { willReadFrequently: true }) : null;
  }, []);

  const saveToHistory = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = getCtx();
    if (canvas && ctx) {
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      setHistory(prev => [...prev, imageData].slice(-20)); // Limit history to last 20 steps
    }
  }, [getCtx]);

  const undo = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = getCtx();
    if (!canvas || !ctx || history.length === 0) return;

    const newHistory = [...history];
    newHistory.pop(); // Remove current state
    const prevState = newHistory[newHistory.length - 1];

    if (prevState) {
      ctx.putImageData(prevState, 0, 0);
    } else {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    }
    setHistory(newHistory);
    setIsSuccess(false);
  }, [history, getCtx]);

  const clearCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = getCtx();
    if (!canvas || !ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setHistory([]);
    setIsSuccess(false);
  }, [getCtx]);

  const initCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const dpr = window.devicePixelRatio || 1;
    const size = container.clientWidth;

    canvas.width = size * dpr;
    canvas.height = size * dpr;
    canvas.style.width = `${size}px`;
    canvas.style.height = `${size}px`;

    const ctx = getCtx();
    if (!ctx) return;
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#1e293b'; 
    ctx.lineWidth = 10;

    clearCanvas();
  }, [clearCanvas, getCtx]);

  useEffect(() => {
    initCanvas();
    window.addEventListener('resize', initCanvas);
    return () => window.removeEventListener('resize', initCanvas);
  }, [initCanvas, item]);

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    setIsDrawing(true);
    setIsSuccess(false);
    draw(e);
  };

  const endDrawing = () => {
    if (isDrawing) {
      saveToHistory();
    }
    setIsDrawing(false);
    const ctx = getCtx();
    if (ctx) ctx.beginPath();
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing) return;
    const canvas = canvasRef.current;
    const ctx = getCtx();
    if (!canvas || !ctx) return;

    const rect = canvas.getBoundingClientRect();
    let x, y;

    if ('touches' in e) {
      if (e.cancelable) e.preventDefault();
      x = e.touches[0].clientX - rect.left;
      y = e.touches[0].clientY - rect.top;
    } else {
      x = e.clientX - rect.left;
      y = e.clientY - rect.top;
    }

    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.moveTo(x, y);
  };

  const handleFinish = () => {
    if (history.length > 0) {
      setIsSuccess(true);
      // Simulate checking delay
      setTimeout(() => {
        // In a real app, we'd compare pixel data or stroke order here
      }, 500);
    }
  };

  return (
    <div className="w-full max-w-lg flex flex-col gap-4">
      <div className="text-center space-y-1">
        <h3 className="text-2xl font-bold text-slate-800 kanji-font">
          {item.reading}
        </h3>
        <p className="text-slate-500 italic">"{item.meaning}"</p>
      </div>

      <div className="relative group" ref={containerRef}>
        {/* Success Overlay */}
        {isSuccess && (
          <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/60 backdrop-blur-[2px] rounded-2xl animate-in zoom-in duration-300 pointer-events-none">
            <div className="bg-green-500 text-white p-4 rounded-full shadow-lg mb-2">
              <Award size={48} className="animate-bounce" />
            </div>
            <p className="text-green-700 font-bold text-xl">Harika Çizim!</p>
            <p className="text-green-600 text-sm">Bir sonraki kelimeye geçebilirsin.</p>
          </div>
        )}

        {/* Trace Guide Background */}
        <div 
          className={`absolute inset-0 flex items-center justify-center pointer-events-none transition-all duration-300 ${
            showGuide ? 'opacity-100' : 'opacity-0'
          }`}
          style={{ opacity: showGuide ? guideOpacity / 100 : 0 }}
        >
          <span 
            className="font-bold text-slate-900 kanji-font select-none"
            style={{ fontSize: `${guideSize}px` }}
          >
            {item.kanji}
          </span>
        </div>

        {/* Drawing Canvas */}
        <canvas
          ref={canvasRef}
          onMouseDown={startDrawing}
          onMouseUp={endDrawing}
          onMouseMove={draw}
          onMouseLeave={endDrawing}
          onTouchStart={startDrawing}
          onTouchEnd={endDrawing}
          onTouchMove={draw}
          className={`bg-white rounded-2xl shadow-inner border border-slate-200 cursor-crosshair touch-none transition-colors ${isSuccess ? 'border-green-300' : ''}`}
        />

        {/* Floating Toolbar */}
        <div className="absolute bottom-4 right-4 flex flex-col gap-2 items-end">
           {showSettings && (
             <div className="flex flex-col gap-3 mb-2 p-4 bg-white/95 backdrop-blur rounded-2xl shadow-2xl border border-slate-200 animate-in fade-in slide-in-from-bottom-2">
                <div className="flex flex-col gap-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase flex items-center gap-1">
                    <Eye size={10} /> Saydamlık (%{guideOpacity})
                  </label>
                  <input 
                    type="range" 
                    min="0" 
                    max="100" 
                    value={guideOpacity} 
                    onChange={(e) => setGuideOpacity(parseInt(e.target.value))}
                    className="w-32 h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                  />
                </div>
                <div className="flex flex-col gap-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase flex items-center gap-1">
                    <Maximize size={10} /> Boyut ({guideSize}px)
                  </label>
                  <input 
                    type="range" 
                    min="100" 
                    max="450" 
                    value={guideSize} 
                    onChange={(e) => setGuideSize(parseInt(e.target.value))}
                    className="w-32 h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                  />
                </div>
             </div>
           )}

           <div className="flex gap-2">
            <button 
              onClick={() => setShowSettings(!showSettings)}
              className={`p-3 rounded-full shadow-lg transition-all ${
                showSettings ? 'bg-indigo-100 text-indigo-600' : 'bg-white text-slate-600 hover:bg-slate-50'
              }`}
              title="Ayarlar"
            >
              <Settings size={20} />
            </button>
            <button 
              onClick={undo}
              disabled={history.length === 0}
              className={`p-3 rounded-full shadow-lg transition-all bg-white text-slate-600 hover:bg-slate-50 ${history.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
              title="Geri Al"
            >
              <RotateCcw size={20} />
            </button>
            <button 
              onClick={clearCanvas}
              className="p-3 bg-white text-pink-500 rounded-full shadow-lg hover:bg-pink-50 transition-all"
              title="Temizle"
            >
              <Eraser size={20} />
            </button>
            <button 
              onClick={handleFinish}
              disabled={history.length === 0 || isSuccess}
              className={`p-3 rounded-full shadow-lg transition-all ${
                isSuccess ? 'bg-green-500 text-white' : 'bg-indigo-600 text-white hover:bg-indigo-700'
              } ${history.length === 0 ? 'opacity-50 cursor-not-allowed' : ''}`}
              title="Kontrol Et"
            >
              <CheckCircle2 size={20} />
            </button>
          </div>
        </div>
      </div>

      <div className="text-center">
        <p className="text-xs text-slate-400 font-medium tracking-wide uppercase">
          {isSuccess ? "Başarıyla tamamladın!" : "Kanji'yi rehbere uygun şekilde çiz ve bitirince 'Kontrol Et'e bas."}
        </p>
      </div>
    </div>
  );
};

export default DrawingBoard;

