      const isUserAlpha = userData[i] > 10;

      if (isRefAlpha) {
        totalRefPixels++;
        if (isUserAlpha) {
          hits++;
        }
      } else if (isUserAlpha) {
        userOutliers++;
      }
    }

    const coverage = (hits / totalRefPixels) * 100;
    // Penalty for scribbling outside (optional but good for strictness)
    const noiseLevel = (userOutliers / totalRefPixels) * 100;

    // Heuristic: Over 55% coverage is usually a decent human trace
    // Noise level check: If user drew 3x more pixels outside than the total size of Kanji, they probably just filled the screen.
    if (coverage > 55 && noiseLevel < 150) {
      setIsSuccess(true);
    } else {
      setIsFailed(true);
    }

    setIsChecking(false);
  };

