             <div className="bg-red-50 text-red-500 px-6 py-4 rounded-3xl border border-red-100 shadow-xl flex items-center gap-3">
                <AlertCircle size={24} />
                <div className="text-left">
                  <p className="font-bold text-sm leading-tight">Biraz daha dikkat!</p>
                  <p className="text-[10px] opacity-80">Rehberi takip etmeye çalış.</p>
                </div>
             </div>
