import React, { useRef, useState, useEffect, useCallback } from 'react';
import { Eraser, Eye, EyeOff, Settings, Maximize, RotateCcw, CheckCircle2, Award, X, AlertCircle, Loader2, PenTool, Sparkles } from 'lucide-react';
import { KanjiItem } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

interface DrawingBoardProps {
  item: KanjiItem;
}

const DrawingBoard: React.FC<DrawingBoardProps> = ({ item }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [isDrawing, setIsDrawing] = useState(false);
  const [showGuide, setShowGuide] = useState(true);
  const [showSettings, setShowSettings] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isFailed, setIsFailed] = useState(false);
  const [isChecking, setIsChecking] = useState(false);
  const [history, setHistory] = useState<ImageData[]>([]);

  const [guideOpacity, setGuideOpacity] = useState(12); 
  const [guideSize, setGuideSize] = useState(240);
  const [penWidth, setPenWidth] = useState(12);
  const [aiFeedback, setAiFeedback] = useState<string>("");

  const getCtx = useCallback(() => {
    const canvas = canvasRef.current;
    return canvas ? canvas.getContext('2d', { willReadFrequently: true }) : null;
  }, []);

  const saveToHistory = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = getCtx();
    if (canvas && ctx) {
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      setHistory(prev => [...prev, imageData].slice(-20));
    }
  }, [getCtx]);

  const undo = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = getCtx();
    if (!canvas || !ctx || history.length === 0) return;

    const newHistory = [...history];
    newHistory.pop();
    const prevState = newHistory[newHistory.length - 1];

    if (prevState) {
      ctx.putImageData(prevState, 0, 0);
    } else {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    }
    setHistory(newHistory);
    setIsSuccess(false);
    setIsFailed(false);
    setAiFeedback("");
  }, [history, getCtx]);

  const clearCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    const ctx = getCtx();
    if (!canvas || !ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setHistory([]);
    setIsSuccess(false);
    setIsFailed(false);
    setAiFeedback("");
  }, [getCtx]);

  const initCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const dpr = window.devicePixelRatio || 1;
    const size = Math.min(container.clientWidth, 450);

    canvas.width = size * dpr;
    canvas.height = size * dpr;
    canvas.style.width = `${size}px`;
    canvas.style.height = `${size}px`;

    const ctx = getCtx();
    if (!ctx) return;
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#1e293b'; 
    ctx.lineWidth = penWidth;

    clearCanvas();
  }, [clearCanvas, getCtx, penWidth]);

  useEffect(() => {
    initCanvas();
    window.addEventListener('resize', initCanvas);
    return () => window.removeEventListener('resize', initCanvas);
  }, [initCanvas, item]);

  useEffect(() => {
    const ctx = getCtx();
    if (ctx) {
      ctx.lineWidth = penWidth;
    }
  }, [penWidth, getCtx]);

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    setIsDrawing(true);
    setIsSuccess(false);
    setIsFailed(false);
    setAiFeedback("");
    draw(e);
  };

  const endDrawing = () => {
    if (isDrawing) saveToHistory();
    setIsDrawing(false);
    const ctx = getCtx();
    if (ctx) ctx.beginPath();
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing) return;
    const canvas = canvasRef.current;
    const ctx = getCtx();
    if (!canvas || !ctx) return;

    const rect = canvas.getBoundingClientRect();
    let x, y;

    if ('touches' in e) {
      if (e.cancelable) e.preventDefault();
      x = e.touches[0].clientX - rect.left;
      y = e.touches[0].clientY - rect.top;
    } else {
      x = e.clientX - rect.left;
      y = e.clientY - rect.top;
    }

    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.moveTo(x, y);
  };

  const handleCheck = async () => {
    if (history.length === 0 || isChecking) return;

    setIsChecking(true);
    setIsFailed(false);
    setIsSuccess(false);
    setAiFeedback("Analiz ediliyor...");

    try {
      const canvas = canvasRef.current;
      if (!canvas) throw new Error("Canvas not found");

      // Prepare image for AI
      const imageData = canvas.toDataURL("image/png").split(',')[1];

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `You are a Japanese Kanji teacher. Look at this drawing and determine if it correctly represents the Kanji character: "${item.kanji}". 
      Respond strictly in JSON format. The feedback should be in Turkish.
      Example: { "isCorrect": true, "feedback": "Harika bir deneme!" }`;

      const result = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: {
          parts: [
            { inlineData: { data: imageData, mimeType: "image/png" } },
            { text: prompt }
          ]
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              isCorrect: { type: Type.BOOLEAN },
              feedback: { type: Type.STRING }
            },
            required: ["isCorrect", "feedback"]
          }
        }
      });

      const response = JSON.parse(result.text || "{}");

      if (response.isCorrect) {
        setIsSuccess(true);
      } else {
        setIsFailed(true);
      }
      setAiFeedback(response.feedback || "");

    } catch (error) {
      console.error("AI Check failed:", error);
      setAiFeedback("Bağlantı hatası oluştu, lütfen tekrar deneyin.");
      setIsFailed(true);
    } finally {
      setIsChecking(false);
    }
  };

  return (
    <div className="w-full max-w-lg flex flex-col gap-6">
      <div className="flex flex-col items-center text-center px-4">
        <h3 className="text-3xl font-bold text-slate-800 kanji-font tracking-tight">
          {item.reading}
        </h3>
        <p className="text-rose-400 font-semibold text-lg mt-1">{item.meaning}</p>
      </div>

      <div className="relative group bg-white p-2 rounded-[2.5rem] shadow-2xl shadow-rose-100 border border-rose-50" ref={containerRef}>

        {/* State Overlays */}
        {isSuccess && (
          <div className="absolute inset-2 z-20 flex flex-col items-center justify-center bg-white/80 backdrop-blur-sm rounded-[2rem] animate-in zoom-in duration-300 pointer-events-none">
            <div className="bg-rose-400 text-white p-5 rounded-full shadow-lg shadow-rose-200 mb-4 animate-bounce">
              <Award size={48} />
            </div>
            <p className="text-rose-600 font-bold text-2xl">Başarılı!</p>
            <p className="text-rose-400 text-sm font-medium mt-1 px-8 text-center">{aiFeedback}</p>
          </div>
        )}

        {isFailed && !isChecking && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-20 flex flex-col items-center justify-center animate-in fade-in duration-300 pointer-events-none w-full px-8">
             <div className="bg-red-50 text-red-500 px-6 py-4 rounded-3xl border border-red-100 shadow-xl flex items-center gap-3">
                <AlertCircle size={24} className="flex-shrink-0" />
                <div className="text-left">
                  <p className="font-bold text-sm leading-tight">Yapay Zeka Notu:</p>
                  <p className="text-[10px] sm:text-xs opacity-80 mt-1">{aiFeedback || "Karakter tam olarak tanınamadı."}</p>
                </div>
             </div>
          </div>
        )}

        {/* Trace Guide Background */}
        <div 
          className={`absolute inset-0 flex items-center justify-center pointer-events-none transition-all duration-500 ${
            showGuide ? 'opacity-100' : 'opacity-0'
          }`}
          style={{ opacity: showGuide ? guideOpacity / 100 : 0 }}
        >
          <span 
            className="font-bold text-slate-900 kanji-font select-none"
            style={{ fontSize: `${guideSize}px` }}
          >
            {item.kanji}
          </span>
        </div>

        {/* Drawing Canvas */}
        <canvas
          ref={canvasRef}
          onMouseDown={startDrawing}
          onMouseUp={endDrawing}
          onMouseMove={draw}
          onMouseLeave={endDrawing}
          onTouchStart={startDrawing}
          onTouchEnd={endDrawing}
          onTouchMove={draw}
          className={`bg-white rounded-[2rem] cursor-crosshair touch-none transition-all duration-500 ${
            isSuccess ? 'ring-8 ring-rose-100' : isFailed ? 'ring-8 ring-red-50' : 'shadow-inner'
          }`}
        />

        {/* Action Controls */}
        <div className="absolute top-4 right-4 flex flex-col gap-3 z-30">
          <button 
            onClick={() => setShowSettings(!showSettings)}
            className={`p-3 rounded-2xl shadow-lg transition-all ${
              showSettings ? 'bg-rose-400 text-white rotate-90' : 'bg-white text-rose-300 hover:text-rose-500'
            }`}
            title="Ayarlar"
          >
            <Settings size={20} />
          </button>

          <button 
            onClick={() => setShowGuide(!showGuide)}
            className={`p-3 rounded-2xl shadow-lg transition-all ${
              showGuide ? 'bg-sky-400 text-white' : 'bg-white text-sky-200 hover:text-sky-400'
            }`}
            title={showGuide ? "Rehberi Gizle" : "Rehberi Göster"}
          >
            {showGuide ? <EyeOff size={20} /> : <Eye size={20} />}
          </button>
        </div>

        {/* Bottom Actions */}
        <div className="absolute bottom-4 left-4 right-4 flex justify-between items-end z-30">
          <div className="flex gap-2">
            <button 
              onClick={undo}
              disabled={history.length === 0 || isChecking}
              className={`p-3 bg-white text-slate-400 rounded-2xl shadow-lg transition-all hover:text-rose-500 hover:bg-rose-50 ${history.length === 0 ? 'opacity-30' : ''}`}
              title="Geri Al"
            >
              <RotateCcw size={20} />
            </button>
            <button 
              onClick={clearCanvas}
              disabled={isChecking}
              className="p-3 bg-white text-slate-400 rounded-2xl shadow-lg hover:text-rose-500 hover:bg-rose-50 transition-all disabled:opacity-30"
              title="Temizle"
            >
              <Eraser size={20} />
            </button>
          </div>

          <button 
            onClick={handleCheck}
            disabled={history.length === 0 || isSuccess || isChecking}
            className={`px-6 py-3 rounded-2xl shadow-xl font-bold flex items-center gap-2 transition-all active:scale-95 ${
              isSuccess 
                ? 'bg-rose-500 text-white' 
                : 'bg-white text-rose-500 hover:bg-rose-50 ring-1 ring-rose-100 shadow-rose-100/50'
            } ${history.length === 0 || isChecking ? 'opacity-30 cursor-not-allowed' : ''}`}
          >
            {isChecking ? <Loader2 size={20} className="animate-spin" /> : <Sparkles size={20} className="text-rose-400" />}
            <span>{isChecking ? 'AI Kontrolü...' : 'AI ile Kontrol Et'}</span>
          </button>
        </div>

        {/* Settings Panel */}
        {showSettings && (
          <div className="absolute top-20 right-4 w-56 p-5 bg-white/95 backdrop-blur rounded-[2rem] shadow-2xl border border-rose-100 z-50 animate-in fade-in slide-in-from-top-4 duration-300">
            <div className="flex items-center justify-between mb-4">
              <span className="text-[10px] font-black text-rose-300 uppercase tracking-widest">Çizim Ayarları</span>
              <button onClick={() => setShowSettings(false)} className="text-rose-200 hover:text-rose-400">
                <X size={14} />
              </button>
            </div>
            <div className="space-y-5">
              <div className="flex flex-col gap-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase flex items-center justify-between">
                  <span className="flex items-center gap-1"><Eye size={10} /> Saydamlık</span> <span>%{guideOpacity}</span>
                </label>
                <input 
                  type="range" min="0" max="100" value={guideOpacity} 
