              <div className="flex flex-col gap-2 border-t border-rose-50 pt-4">
                <label className="text-[10px] font-bold text-slate-400 uppercase flex items-center justify-between">
                  <span className="flex items-center gap-1"><PenTool size={10} /> Kalem Kalınlığı</span> <span>{penWidth}px</span>
