                  className="w-full h-1.5 bg-rose-50 rounded-lg appearance-none cursor-pointer accent-sky-400"
                />
              </div>
            </div>
          </div>
        )}
      </div>

      <p className="text-center text-xs font-bold text-rose-200 uppercase tracking-[0.2em] flex items-center justify-center gap-2">
        {isChecking ? "Zeka analiz yapıyor..." : isSuccess ? "Mükemmel sonuç!" : isFailed ? "Hata: Tekrar deneyebilirsin." : <><Sparkles size={12}/> Gemini AI Destekli Kontrol</>}
      </p>
    </div>
  );
