import { GoogleGenAI, Type } from "@google/genai";

interface DrawingBoardProps {
  item: KanjiItem;
}

type BrushType = 'pen' | 'calligraphy' | 'marker';
type CanvasBg = 'white' | 'cream' | 'dark';

const DrawingBoard: React.FC<DrawingBoardProps> = ({ item }) => {
