      </div>

      <div className={`relative group p-2 rounded-[2.5rem] shadow-2xl shadow-rose-100 border border-rose-50 transition-colors duration-500 ${getBgClass()}`} ref={containerRef}>

        {/* State Overlays */}
        {isSuccess && (
          <div className="absolute inset-2 z-20 flex flex-col items-center justify-center bg-white/80 backdrop-blur-sm rounded-[2rem] animate-in zoom-in duration-300 pointer-events-none">
            <div className="bg-rose-400 text-white p-6 rounded-full shadow-lg shadow-rose-200 mb-4 animate-bounce">
              <Award size={64} />
            </div>
            <p className="text-rose-600 font-bold text-3xl">Başarılı!</p>
            <p className="text-rose-400 text-lg font-medium mt-2 px-12 text-center">{aiFeedback}</p>
          </div>
        )}

        {isFailed && !isChecking && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-20 flex flex-col items-center justify-center animate-in fade-in duration-300 pointer-events-none w-full px-8">
             <div className="bg-red-50 text-red-600 px-8 py-6 rounded-[2rem] border border-red-100 shadow-2xl flex items-center gap-4">
                <AlertCircle size={32} className="flex-shrink-0" />
                <div className="text-left">
                  <p className="font-bold text-lg leading-tight">Geri Bildirim:</p>
                  <p className="text-sm opacity-90 mt-1">{aiFeedback || "Karakter tanınamadı."}</p>
                </div>
             </div>
          </div>
        )}

        {/* Trace Guide Background */}
        <div 
          className={`absolute inset-0 flex items-center justify-center pointer-events-none transition-all duration-500 ${
            showGuide ? 'opacity-100' : 'opacity-0'
          }`}
          style={{ opacity: showGuide ? guideOpacity / 100 : 0 }}
        >
          <span 
            className={`font-bold kanji-font select-none transition-all duration-300 ${canvasBg === 'dark' ? 'text-slate-400' : 'text-slate-900'}`}
            style={{ fontSize: `${guideSize}px` }}
          >
            {item.kanji}
          </span>
        </div>

        {/* Drawing Canvas */}
        <canvas
          ref={canvasRef}
          onMouseDown={startDrawing}
          onMouseUp={endDrawing}
          onMouseMove={draw}
          onMouseLeave={endDrawing}
          onTouchStart={startDrawing}
          onTouchEnd={endDrawing}
          onTouchMove={draw}
          className={`rounded-[2rem] cursor-crosshair touch-none transition-all duration-500 ${
            isSuccess ? 'ring-8 ring-rose-200' : isFailed ? 'ring-8 ring-red-100' : 'shadow-inner'
          }`}
        />

        {/* Action Controls */}
        <div className="absolute top-6 right-6 flex flex-col gap-4 z-30">
          <button 
            onClick={() => setShowSettings(!showSettings)}
            className={`p-4 rounded-2xl shadow-xl transition-all ${
              showSettings ? 'bg-rose-500 text-white rotate-90 scale-110' : 'bg-white text-rose-300 hover:text-rose-500'
            }`}
            title="Ayarlar"
          >
            <Settings size={24} />
          </button>

          <button 
            onClick={() => setShowGuide(!showGuide)}
            className={`p-4 rounded-2xl shadow-xl transition-all ${
              showGuide ? 'bg-sky-400 text-white scale-110' : 'bg-white text-sky-200 hover:text-sky-400'
            }`}
            title={showGuide ? "Rehberi Gizle" : "Rehberi Göster"}
          >
            {showGuide ? <EyeOff size={24} /> : <Eye size={24} />}
          </button>
        </div>

        {/* Bottom Actions */}
        <div className="absolute bottom-6 left-6 right-6 flex justify-between items-end z-30">
          <div className="flex gap-3">
            <button 
              onClick={undo}
              disabled={history.length === 0 || isChecking}
              className={`p-4 bg-white text-slate-400 rounded-2xl shadow-xl transition-all hover:text-rose-500 hover:bg-rose-50 ${history.length === 0 ? 'opacity-30' : 'active:scale-90'}`}
              title="Geri Al"
            >
