import React, { useState, useEffect } from 'react';
import { KanjiItem } from '../types';
import { CheckCircle2, XCircle, Trophy, RefreshCw, ArrowRight, Brain, BookOpen, AlertCircle } from 'lucide-react';
import { kanjiData } from '../data/kanjiData';

interface Mistake {
  kanji: string;
  correct: string;
  userChoice: string;
  meaning: string;
}

const TestMode: React.FC = () => {
  const [isStarted, setIsStarted] = useState(false);
  const [selectedWeek, setSelectedWeek] = useState<number | 'Tümü'>('Tümü');
  const [testData, setTestData] = useState<KanjiItem[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [options, setOptions] = useState<string[]>([]);
  const [mistakes, setMistakes] = useState<Mistake[]>([]);

  const currentItem = testData[currentIdx];

  const startTest = (week: number | 'Tümü') => {
    const data = week === 'Tümü' 
      ? [...kanjiData] 
      : kanjiData.filter(item => item.week === week);

    const shuffled = data.sort(() => Math.random() - 0.5);
    setTestData(shuffled);
    setSelectedWeek(week);
    setIsStarted(true);
    setCurrentIdx(0);
    setScore(0);
    setMistakes([]);
    setShowResult(false);
  };

  const generateOptions = (correctAnswer: string) => {
    const distractors = kanjiData
      .filter(item => item.reading !== correctAnswer)
      .map(item => item.reading)
      .filter((v, i, a) => a.indexOf(v) === i) // unique readings
      .sort(() => Math.random() - 0.5)
      .slice(0, 3);

    return [...distractors, correctAnswer].sort(() => Math.random() - 0.5);
  };

  useEffect(() => {
    if (isStarted && currentItem) {
      setOptions(generateOptions(currentItem.reading));
      setSelectedIdx(null);
      setIsAnswered(false);
    }
  }, [currentIdx, isStarted, testData]);

  const handleOptionClick = (idx: number) => {
    if (isAnswered) return;
    setSelectedIdx(idx);
    setIsAnswered(true);

    if (options[idx] === currentItem.reading) {
      setScore(prev => prev + 1);
    } else {
      setMistakes(prev => [...prev, {
        kanji: currentItem.kanji,
        correct: currentItem.reading,
        userChoice: options[idx],
        meaning: currentItem.meaning
      }]);
    }
  };

  const handleNext = () => {
    if (currentIdx + 1 < testData.length) {
      setCurrentIdx(prev => prev + 1);
    } else {
      setShowResult(true);
    }
  };

  const resetToMenu = () => {
    setIsStarted(false);
    setShowResult(false);
  };

  if (!isStarted) {
    return (
      <div className="w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in duration-500 border border-rose-50">
        <div className="flex flex-col items-center mb-10">
          <div className="bg-rose-50 w-20 h-20 rounded-3xl flex items-center justify-center mb-6 shadow-inner">
            <Brain size={40} className="text-rose-400" />
          </div>
          <h2 className="text-3xl font-black text-slate-800 mb-2">Sakura Quiz</h2>
          <p className="text-slate-400 text-center max-w-sm">Test etmek istediğin haftayı seç ve kanji bilgilerini ölç!</p>
        </div>

        <div className="grid grid-cols-2 gap-4">
          {[9, 10, 11, 12].map(week => (
            <button
              key={week}
              onClick={() => startTest(week)}
              className="group p-6 bg-white border-2 border-slate-100 rounded-3xl text-left hover:border-rose-300 hover:bg-rose-50/50 transition-all active:scale-95"
            >
              <p className="text-[10px] font-black text-rose-300 uppercase tracking-widest mb-1">Seviye</p>
              <p className="text-xl font-bold text-slate-700">Hafta {week}</p>
            </button>
          ))}
          <button
            onClick={() => startTest('Tümü')}
            className="col-span-2 p-6 bg-rose-400 text-white rounded-3xl flex items-center justify-between hover:bg-rose-500 shadow-lg shadow-rose-200 transition-all active:scale-95"
          >
            <div className="text-left">
              <p className="text-[10px] font-black text-rose-100 uppercase tracking-widest mb-1">Karma Test</p>
              <p className="text-xl font-bold">Tüm Haftalar</p>
            </div>
            <ArrowRight size={24} />
          </button>
        </div>
      </div>
    );
  }

  if (showResult) {
    const successRate = (score / testData.length) * 100;
    return (
      <div className="w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in duration-500 border border-rose-50">
        <div className="text-center mb-10">
          <div className="bg-rose-50 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6">
            <Trophy size={48} className={`transition-all ${successRate > 70 ? 'text-amber-400 scale-110' : 'text-rose-300'}`} />
          </div>
          <h2 className="text-3xl font-black text-slate-800 mb-2">Test Sonucu</h2>
          <p className="text-rose-400 font-bold uppercase tracking-widest text-xs">Hafta {selectedWeek}</p>
        </div>

        <div className="grid grid-cols-2 gap-4 mb-10">
          <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Skor</p>
            <p className="text-3xl font-black text-slate-800">{score} <span className="text-lg text-slate-300">/ {testData.length}</span></p>
          </div>
          <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Başarı</p>
            <p className="text-3xl font-black text-slate-800">%{Math.round(successRate)}</p>
          </div>
        </div>

        {mistakes.length > 0 && (
          <div className="mb-10 text-left">
            <div className="flex items-center gap-2 mb-4">
              <AlertCircle size={18} className="text-red-400" />
              <h3 className="font-black text-slate-600 uppercase text-xs tracking-widest">Hatalarını Gözden Geçir</h3>
            </div>
            <div className="space-y-3 max-h-64 overflow-y-auto pr-2 custom-scrollbar">
              {mistakes.map((mistake, i) => (
                <div key={i} className="flex items-center justify-between p-4 bg-red-50/50 rounded-2xl border border-red-100">
                  <div className="flex items-center gap-4">
                    <span className="text-2xl font-bold kanji-font text-slate-800">{mistake.kanji}</span>
                    <div>
                      <p className="text-xs font-bold text-slate-400">{mistake.meaning}</p>
                      <div className="flex items-center gap-2 mt-0.5">
                        <span className="text-xs px-2 py-0.5 bg-red-100 text-red-500 rounded-md font-bold line-through">{mistake.userChoice}</span>
                        <ArrowRight size={12} className="text-slate-300" />
                        <span className="text-xs px-2 py-0.5 bg-green-100 text-green-600 rounded-md font-bold">{mistake.correct}</span>
                      </div>
                    </div>
                  </div>
                  <BookOpen size={16} className="text-rose-200" />
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="flex gap-4">
          <button 
            onClick={() => startTest(selectedWeek)}
            className="flex-1 py-4 bg-slate-800 text-white rounded-2xl font-bold shadow-xl hover:bg-slate-900 transition-all active:scale-95 flex items-center justify-center gap-2"
          >
            <RefreshCw size={20} />
            Yeniden Başlat
          </button>
          <button 
            onClick={resetToMenu}
            className="flex-1 py-4 bg-white text-rose-400 border-2 border-rose-100 rounded-2xl font-bold hover:bg-rose-50 transition-all active:scale-95 flex items-center justify-center gap-2"
          >
            Ana Menü
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full max-w-lg flex flex-col gap-8">
      {/* Question Card */}
      <div className="bg-white rounded-[2.5rem] shadow-2xl shadow-rose-100 border border-rose-50 p-10 text-center relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1.5 bg-rose-50">
          <div 
            className="h-full bg-rose-400 transition-all duration-500" 
            style={{ width: `${((currentIdx + 1) / testData.length) * 100}%` }}
          ></div>
        </div>

        <div className="mb-4 flex justify-between items-center">
          <span className="px-4 py-1.5 bg-rose-50 text-rose-500 text-[10px] font-black rounded-full uppercase tracking-widest border border-rose-100">
            Soru {currentIdx + 1} / {testData.length}
          </span>
          <button onClick={resetToMenu} className="text-slate-300 hover:text-rose-400 transition-colors">
            <XCircle size={20} />
          </button>
        </div>

        <div className="flex flex-col items-center">
          <h2 className="text-[7rem] font-bold text-slate-800 kanji-font leading-none mb-4 select-none drop-shadow-sm">
            {currentItem?.kanji}
          </h2>
          <p className="text-rose-400 font-bold text-lg mb-2">Bu kelimenin okunuşu hangisidir?</p>
          <p className="text-slate-400 text-sm italic">Anlamı: {currentItem?.meaning}</p>
        </div>
      </div>

      {/* Options Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {options.map((option, idx) => {
          const isCorrect = option === currentItem.reading;
          const isSelected = selectedIdx === idx;

          let buttonClass = "bg-white border-2 border-slate-100 text-slate-600 hover:border-rose-200 hover:bg-rose-50/30";
          if (isAnswered) {
            if (isCorrect) buttonClass = "bg-green-50 border-green-400 text-green-700 shadow-lg shadow-green-100 scale-[1.02]";
            else if (isSelected) buttonClass = "bg-red-50 border-red-400 text-red-700 shadow-lg shadow-red-100";
            else buttonClass = "bg-white border-slate-50 text-slate-300 opacity-50";
          }

          return (
            <button
              key={idx}
              onClick={() => handleOptionClick(idx)}
              disabled={isAnswered}
              className={`p-6 rounded-[1.5rem] font-bold text-xl transition-all duration-300 flex items-center justify-between ${buttonClass} ${!isAnswered ? 'active:scale-95' : ''}`}
            >
              <span className="kanji-font">{option}</span>
              {isAnswered && isCorrect && <CheckCircle2 size={24} className="text-green-500" />}
              {isAnswered && isSelected && !isCorrect && <XCircle size={24} className="text-red-500" />}
            </button>
          );
        })}
      </div>

      {/* Footer Action */}
      <div className="flex justify-center h-16">
        {isAnswered && (
          <button
            onClick={handleNext}
            className="px-10 py-4 bg-slate-800 text-white rounded-2xl font-bold shadow-xl flex items-center gap-3 animate-in slide-in-from-bottom-4 duration-300 hover:bg-slate-900 active:scale-95"
          >
            {currentIdx + 1 === testData.length ? 'Sonuçları Gör' : 'Sıradaki Soru'}
            <ArrowRight size={20} />
          </button>
        )}
      </div>
    </div>
  );
};

export default TestMode;

