    setTestType(type);
    const baseData = selectedWeek === 'Tümü' 
      ? [...kanjiData] 
      : kanjiData.filter(item => item.week === selectedWeek);

    const newQuestions: Question[] = baseData
      .sort(() => Math.random() - 0.5)
      .map(item => ({
        item,
        type,
        options: generateOptions(item, type)
      }));

