import { kanjiData } from '../data/kanjiData';

interface Mistake {
  kanji: string;
  correct: string;
  userChoice: string;
  meaning: string;
  questionType: 'kanji-to-reading' | 'reading-to-kanji';
}

interface Question {
  item: KanjiItem;
  type: 'kanji-to-reading' | 'reading-to-kanji';
  options: string[];
}

type TestStep = 'WEEK_SELECTION' | 'TYPE_SELECTION' | 'TESTING' | 'RESULTS';

const TestMode: React.FC = () => {
  const [step, setStep] = useState<TestStep>('WEEK_SELECTION');
  const [selectedWeek, setSelectedWeek] = useState<number | 'Tümü'>('Tümü');
  const [testType, setTestType] = useState<'kanji-to-reading' | 'reading-to-kanji'>('kanji-to-reading');
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [score, setScore] = useState(0);
  const [mistakes, setMistakes] = useState<Mistake[]>([]);

  // Akıllı Çeldirici Algoritması
  const generateOptions = (item: KanjiItem, type: 'kanji-to-reading' | 'reading-to-kanji') => {
    const isKtoR = type === 'kanji-to-reading';
    const correctAnswer = isKtoR ? item.reading : item.kanji;

    // Potansiyel adayları belirle (doğru cevap hariç)
    const candidates = kanjiData.filter(d => 
      isKtoR ? d.reading !== item.reading : d.kanji !== item.kanji
    );

    // Her adayı benzerlik puanına göre değerlendir
    const scoredCandidates = candidates.map(c => {
      let similarityScore = 0;
      const cVal = isKtoR ? c.reading : c.kanji;

      // 1. AYNI HAFTA (En yüksek ağırlık): Kullanıcı aynı anda öğrendiği kelimeleri karıştırmaya daha meyillidir.
      if (c.week === item.week) {
        similarityScore += 40;
      } else if (Math.abs(c.week - item.week) === 1) {
        // Komşu haftalar
        similarityScore += 15;
      }

      // 2. BAŞLANGIÇ BENZERLİĞİ: Kelimeler aynı hece/karakterle başlıyorsa kafa karıştırıcıdır.
      if (cVal[0] === correctAnswer[0]) {
        similarityScore += 25;
      }

      // 3. UZUNLUK BENZERLİĞİ: Kelime uzunlukları aynıysa şıklar daha dengeli görünür.
      if (Math.abs(cVal.length - correctAnswer.length) === 0) {
        similarityScore += 20;
      } else if (Math.abs(cVal.length - correctAnswer.length) <= 1) {
        similarityScore += 10;
      }

      // 4. RASTGELELİK: Her seferinde aynı 3 şık gelmesin diye biraz tuz ekleyelim.
      similarityScore += Math.random() * 15;

      return { value: cVal, score: similarityScore };
    });

    // En yüksek puanlı (en benzer) 10 aday arasından rastgele 3 tanesini seç
    const topDistractors = scoredCandidates
      .sort((a, b) => b.score - a.score)
      .slice(0, 10)
      .sort(() => Math.random() - 0.5)
      .slice(0, 3)
      .map(c => c.value);

    // Şıkları karıştırıp döndür
    return [...topDistractors, correctAnswer].sort(() => Math.random() - 0.5);
